import{_ as s,o as a,c as i,ae as n}from"./chunks/framework.Dn7Y7LSn.js";const k=JSON.parse('{"title":"Episode 7: Advanced Dependency Management","description":"","frontmatter":{},"headers":[],"relativePath":"module-2/advanced-dependency.md","filePath":"module-2/advanced-dependency.md"}'),p={name:"module-2/advanced-dependency.md"};function t(o,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="episode-7-advanced-dependency-management" tabindex="-1">Episode 7: Advanced Dependency Management <a class="header-anchor" href="#episode-7-advanced-dependency-management" aria-label="Permalink to &quot;Episode 7: Advanced Dependency Management&quot;">​</a></h1><p>কম্পোজারের মাধ্যমে প্যাকেজ ইন্সটল করলে <code>composer.json</code> ফাইল তৈরি হওয়ার সাথে সাথে <code>composer.lock</code> নামে আরেকটি ফাইল তৈরি হয়। আমরা যখন <code>composer install</code> কমান্ড রান করাই, তখন আমাদের প্রজেক্টের প্যাকেজগুলোর ঠিক কোন ভার্সনগুলো (exact version) ব্যবহার করা হচ্ছে, তা এই <code>composer.lock</code> ফাইলে রেকর্ড করা হয়।</p><p>এর সুবিধা হলো, অন্য কেউ এই প্রজেক্ট ক্লোন করে ইন্সটল করলে (বা অন্য পিসিতে নিলে), সেখানেও প্যাকেজগুলোর ঠিক ওই ভার্সনগুলোই ইন্সটল হবে, ফলে ভার্সন কনফ্লিক্টের কোনো ঝামেলা থাকে না।</p><h3 id="development-vs-production-dependencies" tabindex="-1">Development vs Production Dependencies <a class="header-anchor" href="#development-vs-production-dependencies" aria-label="Permalink to &quot;Development vs Production Dependencies&quot;">​</a></h3><p>কিছু প্যাকেজ আমাদের শুধু ডেভেলপমেন্ট এনভায়রনমেন্টে (development environment) লাগে, প্রোডাকশন (production) এনভায়রনমেন্টে লাগে না (যেমন: টেস্টিং প্যাকেজ, ডিবাগিং টুল)। এদেরকে আমরা <code>composer.json</code> ফাইলে <code>require-dev</code> এর মধ্যে রাখতে পারি।</p><p>এজন্য আমাদের প্যাকেজ ইন্সটলের সময় <code>--dev</code> ফ্ল্যাগ দিয়ে কমান্ড চালাতে হবে। যেমন:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nahid/jsonq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dev</span></span></code></pre></div><p>এরপর <code>composer.json</code> ফাইলের আকার হবে এরকম:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;require&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;fakerphp/faker&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^1.23&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;require-dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;nahid/jsonq&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^6.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>যেহেতু প্রোডাকশন সার্ভারে আমাদের ডেভ ডিপেন্ডেন্সিগুলো দরকার নেই, তাই সেখানে প্যাকেজ ইন্সটল করার জন্য আমরা নিচের কমান্ডটি রান করব:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-dev</span></span></code></pre></div><h3 id="useful-composer-commands" tabindex="-1">Useful Composer Commands <a class="header-anchor" href="#useful-composer-commands" aria-label="Permalink to &quot;Useful Composer Commands&quot;">​</a></h3><p>কম্পোজারে অ্যাভেইলঅ্যাবল (available) সব কমান্ড দেখার জন্য শুধু <code>composer</code> লিখে <code>Enter</code> চাপলেই হবে:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span></span></code></pre></div><p>এছাড়া কম্পোজারে আর কী কী কমান্ড রয়েছে, তা দেখার জন্য আমরা <a href="https://getcomposer.org/doc/" target="_blank" rel="noreferrer">কম্পোজারের অফিসিয়াল সাইটের ডকুমেন্টেশন</a> থেকে দেখে নিতে পারি।</p>`,15)])])}const u=s(p,[["render",t]]);export{k as __pageData,u as default};
